// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.List;

import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.impl.MapBindingSet;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.parallel.ResourceLock;
import org.junit.jupiter.api.parallel.Resources;

@ResourceLock(Resources.SYSTEM_PROPERTIES)
class NativeLazyReplayBudgetControlTest {
	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();

	@Test
	void metadataFreeLargeRowsSpillWithinSixteenKiBPolicy() {
		String previous = System.getProperty(NativeCountGroupStore.MAX_BYTES_PROPERTY);
		System.setProperty(NativeCountGroupStore.MAX_BYTES_PROPERTY, "16384");
		long files = NativeLazyResultReplay.OPEN_FILES.get();
		long spills = NativeLazyResultReplay.SPILLS.get();
		NativeExecutionContext context = new NativeExecutionContext();
		var ledger = context.memoryLedger();
		try (context) {
			Value payload = VF.createLiteral("payload".repeat(2048));
			assertTrue(NativeRuntimeValueTable.retainedValueBytes(payload, 0) > 8192L,
					"the two-row result cannot fit in the lazy replay's post-workspace resident share");
			MapBindingSet first = new MapBindingSet();
			first.addBinding("payload", payload);
			MapBindingSet second = new MapBindingSet();
			second.addBinding("payload", payload);
			assertSame(NativeRowProvenance.EMPTY, NativeResultRow.fromBindingSet(first).provenance(),
					"plain mappings carry no retained authority metadata");
			Producer producer = new Producer(List.of(first, second), context.cancellation());
			try (NativeLazyResultReplay replay = new NativeLazyResultReplay(new String[] {"payload"}, context,
					context.cancellation(), producer);
					NativeResultCursor reader = replay.cursor(context.cancellation())) {
				assertEquals(payload, reader.next().cell("payload").value());
				assertEquals(payload, reader.next().cell("payload").value());
				assertNull(reader.next());
				assertEquals(2, producer.position);
				assertEquals(1, producer.closes);
				assertTrue(NativeLazyResultReplay.SPILLS.get() > spills,
						"metadata-free rows are accepted by spilling at the same 16 KiB limit");
			}
		} finally {
			if (previous == null) {
				System.clearProperty(NativeCountGroupStore.MAX_BYTES_PROPERTY);
			} else {
				System.setProperty(NativeCountGroupStore.MAX_BYTES_PROPERTY, previous);
			}
		}
		assertEquals(files, NativeLazyResultReplay.OPEN_FILES.get());
		assertEquals(0L, ledger.usedBytes());
	}

	private static final class Producer implements NativeResultCursor {
		private final List<BindingSet> rows;
		private final NativeCancellationToken cancellation;
		private int position;
		private int closes;

		private Producer(List<BindingSet> rows, NativeCancellationToken cancellation) {
			this.rows = rows;
			this.cancellation = cancellation;
		}

		@Override
		public NativeResultRow next() {
			return position == rows.size() ? null : NativeResultRow.fromBindingSet(rows.get(position++));
		}

		@Override
		public NativeCancellationToken cancellation() {
			return cancellation;
		}

		@Override
		public NativeExecutionContext executionContext() {
			return null;
		}

		@Override
		public void close() {
			closes++;
		}
	}
}
